use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's HTTPClient handle is scoped to. A request outside
/// this set would trap at the boundary, so such URLs are reported as failures
/// without ever being requested: one bad subscription must not fail the run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the lowercase host of an http(s) URL, or None if it is not one.
fn host_of(url: &str) -> Option<String> {
    let trimmed = url.trim();
    let lower = trimmed.to_ascii_lowercase();
    let rest = if lower.starts_with("https://") {
        &trimmed[8..]
    } else if lower.starts_with("http://") {
        &trimmed[7..]
    } else {
        return None;
    };

    let end = rest
        .find(|c: char| c == '/' || c == '?' || c == '#' || c == '\\')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    // Drop any userinfo.
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };

    // Drop any port.
    let host = match host_port.find(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };

    if host.is_empty() {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(host) => ALLOWED_HOSTS.iter().any(|h| *h == host),
        None => false,
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input received on this call in the shared store.
        let recorded = subscriptions.urls.join("\n");
        state_rw::put("last-input", &recorded);

        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            if !is_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: String::from("host not in allowlist; not fetched"),
                });
                continue;
            }

            match http_client::fetch(url.trim()) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
